		if r.IsContainer() {
			name = fmt.Sprintf("%s@%s", r.Container.Name, r.ServerName)
			if uuid := getOrCreateServerUUID(r, server); uuid != "" {
				server.UUIDs[r.ServerName] = uuid
			}
		} else if r.IsImage() {
			name = fmt.Sprintf("%s:%s@%s", r.Image.Name, r.Image.Tag, r.ServerName)
			if uuid := getOrCreateServerUUID(r, server); uuid != "" {
				server.UUIDs[r.ServerName] = uuid
			}
		} else {
			name = r.ServerName
		}

