	if err := log.InitLogger(false, false); err != nil {
		t.Errorf("trivy logger failed")
	}

	if err := db.Init(); err != nil {
		t.Errorf("trivy db.Init failed")
	}
	for _, v := range tests {
		lib := LibraryScanner{
			Path: v.path,
			Libs: v.pkgs,
